// Mario Kart 60 FPS patch (MKSC60fps IPS, 2 bytes per region)
#define MKSC_PATCH_LEN	2

struct DrvMkscPatchEntry {
	UINT32 nOffset;
	UINT8  patchData[MKSC_PATCH_LEN];
};

static const DrvMkscPatchEntry MkscPatchU[] = {
	{ 0x030c18, { 0x00, 0x00 } },	// MKSC60fps(USA) / MKSC60fps(EUR)
};

static const DrvMkscPatchEntry MkscPatchJ[] = {
	{ 0x02a718, { 0x00, 0x00 } },	// MKA60fps(JP)
};

static const DrvMkscPatchEntry *pDrvMkscPatch;
static UINT8 DrvMkscOrig[MKSC_PATCH_LEN];
static UINT8 DrvMkscActive;
static UINT8 DrvBiosModeActive;
static INT32 (*pDrvDipMksc)(void);

static INT32 DrvDoReset()
{
	clear_opposite.reset();
//	GbaCoreSetRenderMode(Gba, (DrvDip[GBA_DIPSWITCH_01] & 1));
	GbaCoreSetBiosMode(Gba, (DrvDip[GBA_DIPSWITCH_02] & 1));
	DrvBiosModeActive = (UINT8)(DrvDip[GBA_DIPSWITCH_02] & 1);
	return GbaCoreReset(Gba);
}

// DIP_03 per-game handler: MKSC 60fps patch (toggle -> write ROM + reset)
static INT32 DrvDipMksc()
{
	UINT8 dipOn = DrvDip[GBA_DIPSWITCH_03] & 1;
	if (dipOn == DrvMkscActive)
		return 0;
	const UINT8 *pData = dipOn ? pDrvMkscPatch->patchData : DrvMkscOrig;
	if (GbaCoreWriteRom(Gba, pDrvMkscPatch->nOffset, pData, MKSC_PATCH_LEN))
		return 1;
	DrvMkscActive = dipOn;
	if (DrvDoReset())
		return 1;
	return 0;
}

static INT32 DrvInit()
{
	struct BurnRomInfo ri;
	memset(&ri, 0, sizeof(ri));
	if (BurnDrvGetRomInfo(&ri, 0) || ri.nLen == 0 || ri.nLen > 64 * 1024 * 1024)
		return 1;

	BurnSetRefreshRate(59.72750057);

	UINT32 romSize = ri.nLen;
	if (bDoIpsPatch)
		romSize += nIpsMemExpLen[PRG1_ROM];
	DrvRom = (UINT8 *)BurnMalloc((INT32)romSize);
	if (DrvRom == NULL)
		return 1;
	if (BurnLoadRom(DrvRom, 0, 1))
		return 1;

	// DIP_03 per-game dispatch by short name (MKSC -> 60fps patch)
	DrvMkscActive = 0;
	pDrvMkscPatch = NULL;
	pDrvDipMksc   = NULL;
	if (strcmp(BurnDrvGetTextA(DRV_NAME), "gba_mariokrt") == 0 || strcmp(BurnDrvGetTextA(DRV_NAME), "gba_mariokrtu") == 0) {
		pDrvMkscPatch = MkscPatchU;
	} else if (strcmp(BurnDrvGetTextA(DRV_NAME), "gba_mariokrtj") == 0) {
		pDrvMkscPatch = MkscPatchJ;
	}
	if (pDrvMkscPatch != NULL) {
		if ((UINT64)pDrvMkscPatch->nOffset + MKSC_PATCH_LEN > romSize) {
			pDrvMkscPatch = NULL;
		} else {
			memcpy(DrvMkscOrig, DrvRom + pDrvMkscPatch->nOffset, MKSC_PATCH_LEN);
			pDrvDipMksc = DrvDipMksc;
		}
	}

	if (GbaCoreInit(&Gba))
		return 1;

	GbaCoreSetRenderMode(Gba, (DrvDip[GBA_DIPSWITCH_01] & 1));
	GbaCoreSetBiosMode(Gba, (DrvDip[GBA_DIPSWITCH_02] & 1));
	DrvBiosModeActive = (UINT8)(DrvDip[GBA_DIPSWITCH_02] & 1);

	memset(&ri, 0, sizeof(ri));
	if (BurnDrvGetRomInfo(&ri, 0x80) == 0 && ri.nType && ri.nLen == 0x4000) {
		DrvBios = (UINT8 *)BurnMalloc(0x4000);
		if (DrvBios && BurnLoadRom(DrvBios, 0x80, 1) == 0) {
			if (GbaCoreLoadBios(Gba, DrvBios, 0x4000))
				return 1;
		} else {
			BurnFree(DrvBios);
		}
	}

	tm localTime;
	memset(&localTime, 0, sizeof(localTime));
	BurnGetLocalTime(&localTime);
	GbaRtcSeed rtcSeed;
	rtcSeed.year    = (UINT16)(localTime.tm_year + 1900);
	rtcSeed.month   = (UINT8) (localTime.tm_mon + 1);
	rtcSeed.day     = (UINT8)  localTime.tm_mday;
	rtcSeed.weekday = (UINT8)  localTime.tm_wday;
	rtcSeed.hour    = (UINT8)  localTime.tm_hour;
	rtcSeed.minute  = (UINT8)  localTime.tm_min;
	rtcSeed.second  = (UINT8)  localTime.tm_sec;
	bprintf(PRINT_NORMAL, _T("GBA RTC seed: %04d-%02d-%02d %02d:%02d:%02d (wday %d)\n"),
		rtcSeed.year, rtcSeed.month, rtcSeed.day, rtcSeed.hour, rtcSeed.minute, rtcSeed.second, rtcSeed.weekday);
	if (GbaCoreLoadRom(Gba, DrvRom, romSize, &rtcSeed))
		return 1;

	DrvStateSize = (INT32)GbaCoreStateSize();
	DrvState     = (UINT8*)BurnMalloc(DrvStateSize);
	DrvBattery   = (UINT8*)BurnMalloc((INT32)GbaCoreGetBatteryCapacity());
	if (DrvState == NULL || DrvBattery == NULL)
		return 1;

	DrvBatterySize = (INT32)GbaCoreGetBatterySize(Gba);
	bprintf(PRINT_NORMAL, _T("GBA cartridge features: %08x, battery: %d\n"), GbaCoreGetCartridgeFeatures(Gba), DrvBatterySize);
	if (DrvBatterySize > 0) {
		memcpy(DrvBattery, GbaCoreGetBatteryDataConst(Gba), DrvBatterySize);
	}

	GbaCoreClearAudio(Gba);
	DrvRecalc        = 1;
	DrvSolar         = 0;
	DrvSolarUpLast   = 0;
	DrvSolarDownLast = 0;
	DrvGyroZ         = 0x8000;
	DrvTiltX         = 0x8000;
	DrvTiltY         = 0x8000;

	return 0;
}

static INT32 DrvExit()
{
	GbaCoreExit(&Gba);
	BurnFree(DrvRom);
	BurnFree(DrvBios);
	BurnFree(DrvState);
	BurnFree(DrvBattery);
	DrvBiosModeActive = 0;
	pDrvDipMksc       = NULL;

	DrvStateSize     = 0;
	DrvBatterySize   = 0;
	DrvSolar         = 0;
	DrvSolarUpLast   = 0;
	DrvSolarDownLast = 0;
	DrvGyroZ         = 0x8000;
	DrvTiltX         = 0x8000;
	DrvTiltY         = 0x8000;

	DrvMkscActive = 0;
	pDrvMkscPatch = NULL;

	return 0;
}

static double DrvAudioRate()
{
	return nBurnSoundLen * (GBA_MASTER_CLOCK / 280896.0);
}

static INT32 DrvDraw()
{
	const UINT32 *framebuffer = GbaCoreGetFramebuffer(Gba);
	if (framebuffer == NULL || pBurnDraw == NULL)
		return 0;

	for (INT32 y = 0; y < GBA_HEIGHT; y++) {
		UINT8 *dest = pBurnDraw + y * nBurnPitch;
		const UINT32 *source = framebuffer + y * GBA_WIDTH;
		for (INT32 x = 0; x < GBA_WIDTH; x++) {
			UINT32 pixel = source[x];
			PutPix(dest + x * nBurnBpp, BurnHighCol(pixel & 0xff, (pixel >> 8) & 0xff, (pixel >> 16) & 0xff, 0));
		}
	}

	return 0;
}

static INT32 DrvFrame()
{
	if (DrvReset && !bBurnRunAheadFrame && DrvDoReset())
		return 1;

	// DIP_03: per-game function dispatch (MKSC -> 60fps patch)
	if (!bBurnRunAheadFrame && pDrvDipMksc != NULL) {
		if (pDrvDipMksc())
			return 1;
	}

	// Video rendering DIP: 0 = scanline, 1 = per-pixel; takes effect immediately
	GbaCoreSetRenderMode(Gba, (DrvDip[GBA_DIPSWITCH_01] & 1));

	// BIOS selection DIP: 1 = custom BIOS, 0 = official (if available); change -> reset
	if (!bBurnRunAheadFrame) {
		UINT8 biosDip = DrvDip[GBA_DIPSWITCH_02] & 1;
		if (biosDip != DrvBiosModeActive) {
			if (DrvDoReset())
				return 1;
		}
	}

	// Compile digital inputs
	DrvInput[0] = 0x0000;
	for (INT32 i = 0; i < 10; i++) {
		DrvInput[0] |= ((DrvJoy[i] & 1) << i);
	}
	
	// Apply SOCD processing to directional inputs
	clear_opposite.check(0, DrvInput[0], 0x0010, 0x0020, 0x0040, 0x0080, nSocd[0]);

	GbaInput input;
	memset(&input, 0, sizeof(input));
	input.gyroZ = GbaMotionAxisToInput(DrvGyroZ);
	input.tiltX = GbaMotionAxisToInput(DrvTiltX);
	input.tiltY = GbaMotionAxisToInput(DrvTiltY);
	if (DrvSolarUp && !DrvSolarDown && !DrvSolarUpLast && DrvSolar < GBA_SOLAR_LEVEL_MAX) {
		DrvSolar++;
	} else if (DrvSolarDown && !DrvSolarUp && !DrvSolarDownLast && DrvSolar > 0) {
		DrvSolar--;
	}
	DrvSolarUpLast   = DrvSolarUp;
	DrvSolarDownLast = DrvSolarDown;
	input.solar      = GbaSolarLevelToInput((UINT8)DrvSolar);
	input.buttons    = DrvInput[0];

	GbaCoreSetInput(Gba, &input);

	INT32  runAhead  = bBurnRunAheadFrame != 0;
	double audioRate = nBurnSoundLen > 0 ? DrvAudioRate() : 0.0;
	if (GbaCoreConfigureAudio(Gba, audioRate, nBurnSoundLen, !runAhead && nBurnSoundLen > 0))
		return 1;
	if (GbaCoreRunFrame(Gba))
		return 1;
	if (!runAhead && GbaCoreRenderAudio(Gba, pBurnSoundOut, nBurnSoundLen) != nBurnSoundLen)
		return 1;

	if (pBurnDraw) {
		DrvDraw();
	}

	return 0;
}

static INT32 DrvScan(INT32 nAction, INT32 *pnMin)
{
	if (pnMin) {
		*pnMin = 0x02970e;
	}

	if ((nAction & ACB_VOLATILE) && Gba && DrvState) {
		SCAN_VAR(DrvSolar);
		clear_opposite.scan();
		if (nAction & ACB_WRITE) {
			if (DrvSolar > GBA_SOLAR_LEVEL_MAX)
				DrvSolar = GbaSolarLegacyToLevel(DrvSolar);
			DrvSolarUpLast   = DrvSolarUp;
			DrvSolarDownLast = DrvSolarDown;
			ScanVar(DrvState, DrvStateSize, "gba_machine");
			if (GbaCoreLoadState(Gba, DrvState, DrvStateSize, (nAction & ACB_RUNAHEAD) != 0))
				return 1;
		} else {
			if (GbaCoreSaveState(Gba, DrvState, DrvStateSize))
				return 1;
			ScanVar(DrvState, DrvStateSize, "gba_machine");
		}
	}

	if ((nAction & ACB_NVRAM) && Gba && DrvBattery && DrvBatterySize > 0) {
		if (nAction & ACB_WRITE) {
			ScanVar(DrvBattery, DrvBatterySize, "gba_battery");
			if (GbaCoreLoadBattery(Gba, DrvBattery, DrvBatterySize))
				return 1;
		} else {
			memcpy(DrvBattery, GbaCoreGetBatteryDataConst(Gba), DrvBatterySize);
			ScanVar(DrvBattery, DrvBatterySize, "gba_battery");
			if (!(nAction & ACB_RUNAHEAD))
				GbaCoreClearBatteryDirty(Gba);
		}
	}

	return 0;
}

#undef MKSC_PATCH_LEN

static INT32 GbaGetZipName(char **pszName, UINT32 i)
{
	static char szFilename[MAX_PATH];
	char *pszGameName = NULL;

	if (pszName == NULL)
		return 1;

	if (i == 0) {
		pszGameName = BurnDrvGetTextA(DRV_NAME);
	} else if (i == 1 && BurnDrvGetTextA(DRV_BOARDROM)) {
		pszGameName = BurnDrvGetTextA(DRV_BOARDROM);
	} else {
		pszGameName = BurnDrvGetTextA(DRV_PARENT);
	}

	if (pszGameName == NULL || i > 2) {
		*pszName = NULL;
		return 1;
	}

	strncpy(szFilename, pszGameName, MAX_PATH - 1);
	szFilename[MAX_PATH - 1] = 0;
	if (strncmp(szFilename, "gba_", 4) == 0) {
		memmove(szFilename, szFilename + 4, strlen(szFilename + 4) + 1);
	}
	*pszName = szFilename;

	return 0;
}

